import React, { useState, useRef } from 'react';
import { v4 as uuidv4 } from 'uuid';

// ── Source indicator ─────────────────────────────────────────────
// Live-stream notes: thought.source === 'stream' (or undefined for old notes)
// Retrospective notes: thought.source === 'archive'
const isRetro = (t) => t.source === 'archive';

// ── Copy button ──────────────────────────────────────────────────
function CopyBtn({ text, label = 'copy' }) {
  const [done, setDone] = useState(false);
  return (
    <button onClick={() => { navigator.clipboard?.writeText(text); setDone(true); setTimeout(() => setDone(false), 1400); }}
      style={{ fontSize: 10, color: done ? 'var(--green)' : 'var(--ink-4)', background: 'none', border: '1px solid var(--paper-3)', borderRadius: 5, padding: '2px 8px', cursor: 'pointer', fontFamily: 'var(--font-mono)', fontStyle: 'normal' }}>
      {done ? '✓' : label}
    </button>
  );
}

// ── Single note card ─────────────────────────────────────────────
function NoteCard({ thought, thoughtTypes, onDelete }) {
  const typeInfo = thoughtTypes.find(t => t.id === thought.type) || { color: '#7a6a52', bg: '#f0e8d8', label: thought.type };
  const retro = isRetro(thought);
  const copyText = [thought.quote && `"${thought.quote}"`, thought.text].filter(Boolean).join('\n\n');

  return (
    <div style={{
      background: retro ? 'var(--paper-2)' : 'var(--paper-card)',
      border: '1px solid var(--paper-3)',
      borderLeft: `3px solid ${typeInfo.color}`,
      borderRadius: 8,
      padding: '12px 14px',
      position: 'relative',
      opacity: 1,
    }}
    onMouseEnter={e => { const el = e.currentTarget.querySelector('.note-actions'); if (el) el.style.opacity = '1'; }}
    onMouseLeave={e => { const el = e.currentTarget.querySelector('.note-actions'); if (el) el.style.opacity = '0'; }}>

      {/* Header row */}
      <div style={{ display: 'flex', alignItems: 'center', gap: 7, marginBottom: thought.quote || thought.text ? 8 : 0, paddingRight: 80 }}>
        <span style={{ fontSize: 10, padding: '2px 8px', borderRadius: 20, background: typeInfo.bg + '33', color: typeInfo.color, fontFamily: 'var(--font-mono)', fontStyle: 'normal', border: `1px solid ${typeInfo.color}44` }}>
          {typeInfo.label}
        </span>
        {retro && (
          <span style={{ fontSize: 9, padding: '1px 7px', borderRadius: 10, background: 'var(--blue)', color: '#fff', fontFamily: 'var(--font-mono)', fontStyle: 'normal', letterSpacing: '0.04em', opacity: 0.8 }}>
            retrospective
          </span>
        )}
        {thought.page && <span style={{ fontSize: 10, color: 'var(--ink-4)', fontFamily: 'var(--font-mono)', fontStyle: 'normal' }}>p.{thought.page}</span>}
        {thought.topics?.map(t => <span key={t} style={{ fontSize: 10, color: 'var(--ink-4)', fontFamily: 'var(--font-mono)' }}>#{t}</span>)}
        <span style={{ fontSize: 10, color: 'var(--ink-4)', marginLeft: 'auto', fontStyle: 'italic' }}>
          {new Date(thought.createdAt).toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' })}
        </span>
      </div>

      {/* Quote */}
      {thought.quote && (
        <blockquote style={{ borderLeft: '2px solid var(--paper-3)', paddingLeft: 10, margin: '0 0 8px', fontSize: 13, color: 'var(--ink-2)', fontStyle: 'italic', lineHeight: 1.65 }}>
          "{thought.quote}"
        </blockquote>
      )}

      {/* Note text */}
      {thought.text && (
        <p style={{ fontSize: 13, color: 'var(--ink)', lineHeight: 1.7, margin: 0 }}>{thought.text}</p>
      )}

      {/* Hover actions */}
      <div className="note-actions" style={{ position: 'absolute', top: 10, right: 10, display: 'flex', gap: 5, opacity: 0, transition: 'opacity 0.15s' }}>
        <CopyBtn text={copyText} />
        <button onClick={() => onDelete(thought.id)}
          style={{ fontSize: 10, color: 'var(--ink-4)', background: 'none', border: '1px solid var(--paper-3)', borderRadius: 5, padding: '2px 8px', cursor: 'pointer', fontFamily: 'var(--font-mono)', fontStyle: 'normal' }}
          onMouseEnter={e => e.currentTarget.style.color = 'var(--red)'}
          onMouseLeave={e => e.currentTarget.style.color = 'var(--ink-4)'}>✕</button>
      </div>
    </div>
  );
}

// ── Retrospective capture bar ─────────────────────────────────────
function RetroCaptureBar({ book, thoughtTypes, onAdd }) {
  const [text, setText] = useState('');
  const [quote, setQuote] = useState('');
  const [type, setType] = useState('retrospective');
  const [topics, setTopics] = useState('');
  const [expanded, setExpanded] = useState(false);
  const textRef = useRef();

  const retroType = thoughtTypes.find(t => t.id === 'retrospective') || thoughtTypes[0];
  const defaultType = retroType?.id || thoughtTypes[0]?.id || 'reaction';

  const handleSubmit = () => {
    if (!text.trim() && !quote.trim()) return;
    onAdd({
      id: uuidv4(),
      text: text.trim(),
      quote: quote.trim(),
      bookId: book.id,
      type,
      page: null,
      topics: topics.split(',').map(t => t.trim().toLowerCase()).filter(Boolean),
      source: 'archive',
      createdAt: new Date().toISOString(),
    });
    setText(''); setQuote(''); setTopics(''); setExpanded(false);
    textRef.current?.focus();
  };

  const handleKeyDown = (e) => { if (e.key === 'Enter' && (e.metaKey || e.ctrlKey)) handleSubmit(); };

  return (
    <div style={{
      borderTop: '2px solid var(--blue)',
      background: 'var(--paper-card)',
      padding: expanded ? '14px 20px' : '10px 20px',
    }}>
      {/* Label */}
      <div style={{ display: 'flex', alignItems: 'center', gap: 8, marginBottom: expanded ? 10 : 0 }}>
        <span style={{ fontSize: 10, padding: '1px 8px', borderRadius: 10, background: 'var(--blue)', color: '#fff', fontFamily: 'var(--font-mono)', fontStyle: 'normal', letterSpacing: '0.04em', opacity: 0.85 }}>
          retrospective
        </span>
        {!expanded && (
          <input ref={textRef} value={text}
            onChange={e => { setText(e.target.value); if (e.target.value) setExpanded(true); }}
            onFocus={() => setExpanded(true)} onKeyDown={handleKeyDown}
            placeholder="Add a retrospective note on this book…"
            style={{ flex: 1, border: 'none', background: 'transparent', fontSize: 13, color: 'var(--ink)', outline: 'none', fontStyle: 'italic', fontFamily: 'var(--font-serif)' }} />
        )}
      </div>

      {expanded && (
        <>
          {/* Quote */}
          <div style={{ marginBottom: 8 }}>
            <div style={{ fontSize: 10, color: 'var(--ink-4)', fontFamily: 'var(--font-mono)', fontStyle: 'normal', textTransform: 'uppercase', letterSpacing: '0.05em', marginBottom: 4 }}>Quote (optional)</div>
            <textarea value={quote} onChange={e => setQuote(e.target.value)} rows={2} onKeyDown={handleKeyDown}
              placeholder="A passage you want to revisit…"
              style={{ width: '100%', resize: 'none', border: '1px solid var(--paper-3)', borderRadius: 6, padding: '6px 10px', fontSize: 13, fontStyle: 'italic', color: 'var(--ink-2)', background: 'var(--paper-2)', fontFamily: 'var(--font-serif)' }} />
          </div>

          {/* Main text */}
          <div style={{ marginBottom: 10 }}>
            <div style={{ fontSize: 10, color: 'var(--ink-4)', fontFamily: 'var(--font-mono)', fontStyle: 'normal', textTransform: 'uppercase', letterSpacing: '0.05em', marginBottom: 4 }}>Note / reflection</div>
            <textarea ref={textRef} value={text} onChange={e => setText(e.target.value)} rows={3} onKeyDown={handleKeyDown}
              placeholder="Looking back now, what do you think? How has your view changed?"
              style={{ width: '100%', resize: 'none', border: 'none', background: 'transparent', fontSize: 14, lineHeight: 1.65, color: 'var(--ink)', outline: 'none', fontFamily: 'var(--font-serif)' }} />
          </div>

          {/* Controls */}
          <div style={{ display: 'flex', gap: 8, alignItems: 'center', flexWrap: 'wrap' }}>
            {/* Type selector */}
            <select value={type} onChange={e => setType(e.target.value)}
              style={{ fontSize: 12, padding: '4px 22px 4px 8px', borderRadius: 6, background: 'var(--paper-2)', color: 'var(--ink)', border: '1px solid var(--paper-3)' }}>
              {thoughtTypes.map(t => <option key={t.id} value={t.id}>{t.label}</option>)}
            </select>

            {/* Topics */}
            <input value={topics} onChange={e => setTopics(e.target.value)}
              placeholder="topics, comma separated"
              style={{ flex: 1, minWidth: 140, padding: '4px 10px', fontSize: 12, borderRadius: 6 }} />

            <div style={{ display: 'flex', gap: 6, marginLeft: 'auto' }}>
              <button onClick={() => { setExpanded(false); setText(''); setQuote(''); }}
                style={{ fontSize: 12, padding: '5px 12px', border: '1px solid var(--paper-3)', borderRadius: 6, color: 'var(--ink-3)', cursor: 'pointer', background: 'transparent' }}>
                Cancel
              </button>
              <button onClick={handleSubmit}
                style={{ fontSize: 12, padding: '5px 16px', borderRadius: 6, background: 'var(--blue)', color: '#fff', border: 'none', cursor: 'pointer', fontFamily: 'var(--font-serif)' }}>
                Save <span style={{ opacity: 0.6, fontSize: 10 }}>⌘↵</span>
              </button>
            </div>
          </div>
        </>
      )}
    </div>
  );
}

// ── Book archive panel ────────────────────────────────────────────
function BookArchivePanel({ book, thoughts, thoughtTypes, onClose, onAddThought, onDeleteThought }) {
  const [filterType, setFilterType] = useState('all');
  const [search, setSearch] = useState('');
  const [copied, setCopied] = useState(false);

  const allBookThoughts = thoughts.filter(t => t.bookId === book.id);
  const liveNotes  = allBookThoughts.filter(t => !isRetro(t));
  const retroNotes = allBookThoughts.filter(t => isRetro(t));

  const applyFilter = (list) => list
    .filter(t => filterType === 'all' || t.type === filterType)
    .filter(t => !search ||
      t.text?.toLowerCase().includes(search.toLowerCase()) ||
      t.quote?.toLowerCase().includes(search.toLowerCase()) ||
      t.topics?.some(tp => tp.includes(search.toLowerCase())))
    .sort((a, b) => new Date(a.createdAt) - new Date(b.createdAt));

  const filteredLive  = applyFilter(liveNotes);
  const filteredRetro = applyFilter(retroNotes);

  const usedTypes = [...new Set(allBookThoughts.map(t => t.type))];

  const exportAll = () => {
    const renderNote = (t) => {
      const type = thoughtTypes.find(tp => tp.id === t.type);
      const lines = [`### ${type?.label || t.type}${t.page ? ` (p.${t.page})` : ''}${isRetro(t) ? ' · retrospective' : ''}`];
      if (t.quote) lines.push(`> "${t.quote}"`);
      if (t.text) lines.push(t.text);
      if (t.topics?.length) lines.push(t.topics.map(tp => `#${tp}`).join(' '));
      return lines.join('\n');
    };
    const sections = [
      `# ${book.title}`,
      `**Author:** ${book.author}`,
      book.year ? `**Year:** ${book.year < 0 ? Math.abs(book.year) + ' BCE' : book.year}` : '',
      book.rating ? `**Rating:** ${'★'.repeat(book.rating)}${'☆'.repeat(5 - book.rating)}` : '',
      book.review ? `**Review:** "${book.review}"` : '',
      '',
      liveNotes.length ? ['## Reading notes', '', ...liveNotes.sort((a,b) => new Date(a.createdAt)-new Date(b.createdAt)).map(renderNote)].join('\n') : '',
      retroNotes.length ? ['## Retrospective notes', '', ...retroNotes.sort((a,b) => new Date(a.createdAt)-new Date(b.createdAt)).map(renderNote)].join('\n') : '',
    ].filter(Boolean).join('\n');
    navigator.clipboard?.writeText(sections);
    setCopied(true); setTimeout(() => setCopied(false), 1500);
  };

  const totalCount = filteredLive.length + filteredRetro.length;

  return (
    <div style={{ display: 'flex', flexDirection: 'column', height: '100%' }}>
      {/* Header */}
      <div style={{ padding: '12px 22px 10px', borderBottom: '1px solid var(--paper-3)', display: 'flex', alignItems: 'center', gap: 10, flexShrink: 0, background: 'var(--paper-2)' }}>
        <button onClick={onClose} style={{ fontSize: 13, color: 'var(--ink-3)', cursor: 'pointer', background: 'none', border: 'none' }}>← Archive</button>
        <div style={{ width: 1, height: 16, background: 'var(--paper-3)' }} />
        <div style={{ width: 11, height: 11, borderRadius: '50%', background: book.color, flexShrink: 0 }} />
        <div style={{ flex: 1 }}>
          <div style={{ fontSize: 15, fontWeight: 600, color: 'var(--ink)' }}>{book.title}</div>
          <div style={{ fontSize: 11, color: 'var(--ink-3)', fontStyle: 'italic', marginTop: 1 }}>
            {book.author}{book.year ? ` · ${book.year < 0 ? Math.abs(book.year) + ' BCE' : book.year}` : ''} ·{' '}
            <span style={{ color: 'var(--ink-2)' }}>{liveNotes.length} reading</span> · <span style={{ color: 'var(--blue)', opacity: 0.85 }}>{retroNotes.length} retrospective</span>
          </div>
        </div>
        {book.rating && <span style={{ fontSize: 13, color: '#b07d28', letterSpacing: 1 }}>{'★'.repeat(book.rating)}{'☆'.repeat(5 - book.rating)}</span>}
        <button onClick={exportAll} style={{ fontSize: 12, padding: '5px 14px', borderRadius: 6, border: '1px solid var(--paper-3)', color: copied ? 'var(--green)' : 'var(--ink-2)', background: 'var(--paper-card)', cursor: 'pointer' }}>
          {copied ? '✓ Copied' : 'Copy all'}
        </button>
      </div>

      {/* Review banner */}
      {book.review && (
        <div style={{ padding: '8px 22px', background: 'var(--accent-light)', borderBottom: '1px solid var(--accent-2)' }}>
          <span style={{ fontSize: 11, color: 'var(--accent)', fontFamily: 'var(--font-mono)', fontStyle: 'normal', textTransform: 'uppercase', letterSpacing: '0.05em', marginRight: 10 }}>Review</span>
          <span style={{ fontSize: 13, color: 'var(--ink)', fontStyle: 'italic' }}>"{book.review}"</span>
        </div>
      )}

      {/* Filter strip */}
      <div style={{ padding: '7px 22px', borderBottom: '1px solid var(--paper-3)', display: 'flex', gap: 5, alignItems: 'center', flexShrink: 0, flexWrap: 'wrap' }}>
        <button onClick={() => setFilterType('all')} style={{ fontSize: 11, padding: '2px 9px', borderRadius: 20, border: `1px solid ${filterType === 'all' ? 'var(--ink-3)' : 'var(--paper-3)'}`, background: filterType === 'all' ? 'var(--paper-3)' : 'transparent', color: filterType === 'all' ? 'var(--ink)' : 'var(--ink-3)', cursor: 'pointer' }}>All ({totalCount})</button>
        {usedTypes.map(tid => {
          const type = thoughtTypes.find(t => t.id === tid);
          if (!type) return null;
          const cnt = allBookThoughts.filter(t => t.type === tid).length;
          return (
            <button key={tid} onClick={() => setFilterType(filterType === tid ? 'all' : tid)}
              style={{ fontSize: 11, padding: '2px 9px', borderRadius: 20, border: `1px solid ${filterType === tid ? type.color : 'var(--paper-3)'}`, background: filterType === tid ? type.bg + '44' : 'transparent', color: filterType === tid ? type.color : 'var(--ink-3)', cursor: 'pointer' }}>
              {type.label} {cnt}
            </button>
          );
        })}
        <input value={search} onChange={e => setSearch(e.target.value)} placeholder="Search notes…"
          style={{ marginLeft: 'auto', width: 180, padding: '5px 10px', fontSize: 12 }} />
      </div>

      {/* Notes feed */}
      <div style={{ flex: 1, overflowY: 'auto', padding: '16px 22px', display: 'flex', flexDirection: 'column', gap: 10 }}>

        {/* Live reading notes */}
        {filteredLive.length > 0 && (
          <>
            <div style={{ fontSize: 10, fontWeight: 700, color: 'var(--ink-4)', letterSpacing: '0.08em', textTransform: 'uppercase', fontFamily: 'var(--font-mono)', fontStyle: 'normal', paddingBottom: 6, borderBottom: '1px solid var(--paper-3)', marginBottom: 2 }}>
              Reading notes <span style={{ fontWeight: 400 }}>({filteredLive.length})</span>
            </div>
            {filteredLive.map(t => (
              <NoteCard key={t.id} thought={t} thoughtTypes={thoughtTypes} onDelete={onDeleteThought} />
            ))}
          </>
        )}

        {filteredLive.length === 0 && !search && filterType === 'all' && (
          <div style={{ textAlign: 'center', padding: '20px 0', color: 'var(--ink-4)', fontStyle: 'italic', fontSize: 13 }}>
            No live reading notes captured for this book.
          </div>
        )}

        {/* Retrospective notes section */}
        <div style={{ marginTop: filteredLive.length > 0 ? 16 : 0 }}>
          <div style={{ fontSize: 10, fontWeight: 700, color: 'var(--blue)', letterSpacing: '0.08em', textTransform: 'uppercase', fontFamily: 'var(--font-mono)', fontStyle: 'normal', paddingBottom: 6, borderBottom: '2px solid var(--blue)', marginBottom: 10, opacity: 0.8, display: 'flex', alignItems: 'center', gap: 8 }}>
            Retrospective notes <span style={{ fontWeight: 400 }}>({filteredRetro.length})</span>
            <span style={{ fontSize: 9, fontWeight: 400, color: 'var(--ink-4)', textTransform: 'none', letterSpacing: 0 }}>written after finishing</span>
          </div>
          {filteredRetro.length === 0 ? (
            <div style={{ textAlign: 'center', padding: '16px 0', color: 'var(--ink-4)', fontStyle: 'italic', fontSize: 13 }}>
              No retrospective notes yet — add one below.
            </div>
          ) : filteredRetro.map(t => (
            <NoteCard key={t.id} thought={t} thoughtTypes={thoughtTypes} onDelete={onDeleteThought} />
          ))}
        </div>

        {/* Empty state */}
        {totalCount === 0 && (search || filterType !== 'all') && (
          <div style={{ textAlign: 'center', padding: '40px 0', color: 'var(--ink-4)', fontStyle: 'italic' }}>No notes match.</div>
        )}
      </div>

      {/* Retrospective capture bar */}
      <RetroCaptureBar book={book} thoughtTypes={thoughtTypes} onAdd={onAddThought} />
    </div>
  );
}

// ── Main ArchiveView ─────────────────────────────────────────────
export default function ArchiveView({ books, articles = [], thoughts, thoughtTypes, onAddThought, onDeleteThought, initialItemId, onClearInitial }) {
  const [selectedBookId, setSelectedBookId] = useState(initialItemId || null);
  const [search, setSearch] = useState('');
  const [sortBy, setSortBy] = useState('finished');
  const [typeFilter, setTypeFilter] = useState('all'); // 'all' | 'book' | 'article'

  // Merge finished books and finished articles into one list
  const finishedBooks    = books.filter(b => b.status === 'finished' || b.status === 'dnf').map(b => ({ ...b, _itemType: 'book' }));
  const finishedArticles = articles.filter(a => a.status === 'finished' || a.status === 'dnf').map(a => ({ ...a, _itemType: 'article' }));
  const allFinished = [...finishedBooks, ...finishedArticles];

  const filtered = allFinished
    .filter(item => typeFilter === 'all' || item._itemType === typeFilter)
    .filter(item => !search || item.title.toLowerCase().includes(search.toLowerCase()) || item.author?.toLowerCase().includes(search.toLowerCase()))
    .sort((a, b) => {
      if (sortBy === 'title')  return a.title.localeCompare(b.title);
      if (sortBy === 'rating') return (b.rating || 0) - (a.rating || 0);
      if (sortBy === 'notes')  return thoughts.filter(t => t.bookId === b.id).length - thoughts.filter(t => t.bookId === a.id).length;
      return new Date(b.finishedAt || 0) - new Date(a.finishedAt || 0);
    });

  const selectedItem = allFinished.find(item => item.id === selectedBookId);

  if (selectedItem) {
    return (
      <BookArchivePanel
        book={selectedItem}
        thoughts={thoughts}
        thoughtTypes={thoughtTypes}
        onClose={() => { setSelectedBookId(null); onClearInitial?.(); }}
        onAddThought={onAddThought}
        onDeleteThought={onDeleteThought}
      />
    );
  }

  const totalNotes = thoughts.filter(t => allFinished.some(item => item.id === t.bookId)).length;
  const retroCount = thoughts.filter(t => isRetro(t) && allFinished.some(item => item.id === t.bookId)).length;

  return (
    <div style={{ display: 'flex', flexDirection: 'column', height: '100%' }}>
      {/* Header */}
      <div style={{ padding: '12px 22px 10px', borderBottom: '1px solid var(--paper-3)', display: 'flex', alignItems: 'center', gap: 10, flexShrink: 0 }}>
        <div>
          <div style={{ fontSize: 15, fontWeight: 500, color: 'var(--ink)' }}>Archive</div>
          <div style={{ fontSize: 11, color: 'var(--ink-3)', fontStyle: 'italic', marginTop: 1 }}>
            {finishedBooks.length} book{finishedBooks.length !== 1 ? 's' : ''} · {finishedArticles.length} paper{finishedArticles.length !== 1 ? 's' : ''} · {totalNotes} notes · {retroCount} retrospective
          </div>
        </div>
        <div style={{ marginLeft: 'auto', display: 'flex', gap: 8, alignItems: 'center' }}>
          {/* Type filter */}
          <div style={{ display: 'flex', border: '1px solid var(--paper-3)', borderRadius: 6, overflow: 'hidden' }}>
            {[['all','All'],['book','Books'],['article','Papers']].map(([val, label]) => (
              <button key={val} onClick={() => setTypeFilter(val)}
                style={{ padding: '4px 10px', fontSize: 11, border: 'none', borderRight: val !== 'article' ? '1px solid var(--paper-3)' : 'none', background: typeFilter === val ? 'var(--accent-light)' : 'transparent', color: typeFilter === val ? 'var(--accent)' : 'var(--ink-3)', cursor: 'pointer' }}>
                {label}
              </button>
            ))}
          </div>
          <select value={sortBy} onChange={e => setSortBy(e.target.value)}
            style={{ fontSize: 11, padding: '5px 22px 5px 8px', borderRadius: 6, background: 'var(--paper-2)', color: 'var(--ink-2)', border: '1px solid var(--paper-3)' }}>
            <option value="finished">Date finished</option>
            <option value="rating">Rating</option>
            <option value="notes">Note count</option>
            <option value="title">Title</option>
          </select>
          <input value={search} onChange={e => setSearch(e.target.value)} placeholder="Search…"
            style={{ width: 160, padding: '6px 12px', fontSize: 12 }} />
        </div>
      </div>

      {/* List */}
      <div style={{ flex: 1, overflowY: 'auto', padding: '16px 22px', display: 'flex', flexDirection: 'column', gap: 8 }}>
        {filtered.length === 0 ? (
          <div style={{ textAlign: 'center', padding: '60px 0', color: 'var(--ink-4)', fontStyle: 'italic', fontSize: 14, lineHeight: 1.7 }}>
            {search ? 'No items match.' : 'No finished books or papers yet.'}
          </div>
        ) : filtered.map(item => {
          const allNotes   = thoughts.filter(t => t.bookId === item.id);
          const liveCount  = allNotes.filter(t => !isRetro(t)).length;
          const retro      = allNotes.filter(t => isRetro(t)).length;
          const quoteCount = allNotes.filter(t => t.quote).length;
          const finishedDate = item.finishedAt ? new Date(item.finishedAt).toLocaleDateString('en-US', { month: 'short', year: 'numeric' }) : null;
          const isPaper = item._itemType === 'article';

          return (
            <div key={item.id} onClick={() => setSelectedBookId(item.id)}
              style={{ background: 'var(--paper-card)', border: '1px solid var(--paper-3)', borderRadius: 10, padding: '14px 18px', cursor: 'pointer', display: 'flex', alignItems: 'center', gap: 14, transition: 'box-shadow 0.15s' }}
              onMouseEnter={e => { e.currentTarget.style.boxShadow = 'var(--shadow-sm)'; e.currentTarget.style.borderColor = item.color + '55'; }}
              onMouseLeave={e => { e.currentTarget.style.boxShadow = 'none'; e.currentTarget.style.borderColor = 'var(--paper-3)'; }}>
              <div style={{ width: 4, height: 52, background: item.color, borderRadius: 2, flexShrink: 0 }} />
              <div style={{ flex: 1, minWidth: 0 }}>
                <div style={{ display: 'flex', alignItems: 'center', gap: 6 }}>
                  <div style={{ fontSize: 14, fontWeight: 500, color: 'var(--ink)' }}>{item.title}</div>
                  {isPaper && <span style={{ fontSize: 9, padding: '1px 6px', borderRadius: 8, background: '#e0f0f8', color: '#1a5c7a', fontFamily: 'var(--font-mono)', fontStyle: 'normal', flexShrink: 0 }}>PAPER</span>}
                </div>
                <div style={{ fontSize: 11, color: 'var(--ink-3)', fontStyle: 'italic', marginTop: 2 }}>
                  {item.author}
                  {isPaper && item.journal && <span style={{ color: 'var(--ink-4)' }}> · {item.journal}</span>}
                  {item.year ? ` · ${item.year < 0 ? Math.abs(item.year) + ' BCE' : item.year}` : ''}
                </div>
                {item.review && <div style={{ fontSize: 12, color: 'var(--ink-3)', fontStyle: 'italic', marginTop: 4, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>"{item.review}"</div>}
              </div>
              <div style={{ textAlign: 'right', flexShrink: 0 }}>
                {item.rating && <div style={{ fontSize: 12, color: '#b07d28', marginBottom: 4 }}>{'★'.repeat(item.rating)}{'☆'.repeat(5 - item.rating)}</div>}
                <div style={{ fontSize: 11, color: 'var(--ink-3)' }}>
                  <span style={{ color: 'var(--ink)', fontWeight: 500 }}>{liveCount}</span> notes
                  {retro > 0 && <span style={{ color: 'var(--blue)', opacity: 0.8 }}> · {retro} retro</span>}
                  {quoteCount > 0 && <span style={{ color: 'var(--ink-4)' }}> · {quoteCount} quotes</span>}
                </div>
                {finishedDate && <div style={{ fontSize: 10, color: 'var(--ink-4)', marginTop: 2, fontStyle: 'italic' }}>finished {finishedDate}</div>}
                {item.status === 'dnf' && <div style={{ fontSize: 10, color: 'var(--red)', fontFamily: 'var(--font-mono)', fontStyle: 'normal' }}>DNF</div>}
              </div>
              <div style={{ fontSize: 14, color: 'var(--ink-4)' }}>→</div>
            </div>
          );
        })}
      </div>
    </div>
  );
}
